import pandas as pd

def fx_rate(date: str) -> float:
    df = pd.read_csv('data/ecb_rates_2019.csv', parse_dates=['Date'])
    row = df[df['Date'] == date]
    return float(row['Rate'].values[0])

def normalize_phone(s: str) -> str:
    s = s.replace('-', '').replace(' ', '').replace('(', '').replace(')', '')
    if len(s) == 10:
        return f'({s[:3]}) {s[3:6]}-{s[6:]}'
    return s

def median(nums: list) -> float:
    nums_sorted = sorted(nums)
    n = len(nums_sorted)
    mid = n // 2
    if n % 2 == 0:
        return (nums_sorted[mid - 1] + nums_sorted[mid]) / 2
    else:
        return float(nums_sorted[mid])

